import { loadFont } from "@remotion/google-fonts/Montserrat";
import React from "react";
import { AbsoluteFill, Easing, Img, interpolate, OffthreadVideo, Sequence, staticFile, useCurrentFrame } from "remotion";

// MATHEUS · vídeo 2, versão 7 em 1:1 (1080×1080) montada para o quadrado: tudo dentro de x 120–960 e y 90–990
// (pedido: "refaça as animações para ficar na margem certa"). Mesma montagem e tempos da v7 vertical.
// Base: versão 7: igual à v6, mas as filmagens aparecem INTEIRAS (plano 9:16 completo num cartão vertical,
// sem zoom que corta) — pedido "mostre inteiros". Rostos dos pacientes seguem desfocados nos clipes.
// Base: versão 6: igual à v5, só o gancho (0–3,3 s) trocado por cena desenhada (pedido).
// Base: versão 5. VERTICAL 1080×1920.
// Correção 2 da Nina sobre a v4 + pedido ("diminua o degradê"):
// - degradê/escurecimento leve; nas cenas de vídeo a filmagem vai num cartão de cantos arredondados e o texto fica embaixo,
//   no fundo azul-marinho;
// - "até o seu quarto / até a sua sala" virou a casa em corte (zoom do quarto para a sala); "no ritmo de cada paciente"
//   virou a ficha com barras que enchem;
// - todo plano enquadrado só no Matheus (sem confirmação de autorização dos pacientes); rostos dos pacientes seguem
//   desfocados nos clipes (clipes_v2.py);
// - CASA e SALA grandes (~70% da largura), apoio do nome no mesmo estilo, "SEM TRÂNSITO"/"SEM SALA DE ESPERA" no mesmo
//   lugar com troca do ícone, título da casa azul em 2 níveis e todo branco, tela final preenchida até embaixo.
// Texto abaixo de y 1000 fica com no máximo ~760 px (fora da coluna de botões do Instagram). Voz e tempos iguais à v4.

const { fontFamily: FONT } = loadFont("normal", { weights: ["600", "700", "800", "900"], subsets: ["latin", "latin-ext"] });

export const MF7Q_FPS = 30;
const FPS = MF7Q_FPS;
const LEAD = 0.15;

const C = {
  sair: 0.06, pra: 0.62, fisio: 1.18, ficou: 1.93, dificil: 2.32,
  entao: 3.59, vai: 4.45, voce: 5.39,
  meu: 6.49, sou: 6.83, espec: 8.02,
  atendo: 10.51, casa: 11.52,
  levo: 12.59, quarto: 13.1, sala: 14.61,
  bola: 15.82, faixa: 16.4, pedal: 17.0,
  exerc: 17.65, forca: 18.8, equil: 19.15,
  ritmo: 20.78, cada: 21.64,
  transito: 22.97, espera: 24.2,
  clique: 25.54, fale: 26.0, agende: 26.87, consulta: 27.37, fim: 28.09,
};
const B = 3.3, BZ = 5.95, CN = 6.3, D = 10.3, E = 12.45, F = 15.7, G = 17.5, H = 20.6, I = 22.75, J = 25.4;
const KS = C.fale + 0.95;
export const MF7Q_FRAMES = Math.round((C.fim + 1.3 + LEAD) * FPS);
const fr = (s: number) => Math.round((s + LEAD) * FPS);

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const BACK = Easing.out(Easing.back(1.3));
const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const pop = (t: number, a: number, d = 0.4) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const io = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], { ...cl, easing: INOUT });

const BG = "#0E2A47";
const CARD = "#163A60";
const EDGE = "#24527F";
const BLUE = "#2F8FFF";
const SKY = "#8CCBFF";
const WHITE = "#FFFFFF";
const PAPER = "#EEF5FF";
const RED = "#FF5B5F";

// texto entra pela máscara (sobe da linha) e fica parado; folga grande para Ç e acentos
const Mask: React.FC<{ t: number; at: number; out?: number; children: React.ReactNode }> = ({ t, at, out, children }) => {
  const e = k(t, at, 0.42);
  const o = out === undefined ? 0 : lin(t, out, out + 0.14);
  return (
    <div style={{ overflow: "hidden", padding: "40px 10px 56px", margin: "-40px 0 -56px", opacity: 1 - o }}>
      <div style={{ transform: `translateY(calc(${((1 - e) * 110).toFixed(2)}% + ${((1 - e) * 100).toFixed(1)}px))`, opacity: e > 0 ? 1 : 0 }}>{children}</div>
    </div>
  );
};
const SH = "0 3px 6px rgba(0,0,0,0.4), 0 6px 26px rgba(0,0,0,0.45)";
const T: React.FC<{ size: number; color?: string; weight?: number; caps?: boolean; children: React.ReactNode }> = ({ size, color = WHITE, weight = 900, caps = true, children }) => (
  <div style={{ fontFamily: FONT, fontWeight: weight, fontSize: size, lineHeight: 1.0, letterSpacing: caps ? "-0.01em" : "-0.02em", textTransform: caps ? "uppercase" : "none", color, whiteSpace: "nowrap", textAlign: "center", textShadow: SH }}>{children}</div>
);
const Cap: React.FC<{ size?: number; color?: string; children: React.ReactNode }> = ({ size = 40, color = WHITE, children }) => (
  <div style={{ fontFamily: FONT, fontWeight: 700, fontSize: size, letterSpacing: "0.16em", textTransform: "uppercase", color, whiteSpace: "nowrap", textAlign: "center", textShadow: SH }}>{children}</div>
);
const Col: React.FC<{ y: number; gap?: number; children: React.ReactNode }> = ({ y, gap = 10, children }) => (
  <div style={{ position: "absolute", left: 0, right: 0, top: y, transform: "translateY(-50%)", display: "flex", flexDirection: "column", alignItems: "center", gap }}>{children}</div>
);
type Sw = [React.ReactNode, number];
const Swap: React.FC<{ t: number; items: Sw[] }> = ({ t, items }) => (
  <div style={{ display: "grid", justifyItems: "center" }}>
    {items.map(([n, at], i) => {
      const nx = items[i + 1]?.[1];
      if (t < at - 0.01 || (nx !== undefined && t > nx)) return null;
      return <div key={i} style={{ gridArea: "1 / 1" }}><Mask t={t} at={at} out={nx === undefined ? undefined : nx - 0.15}>{n}</Mask></div>;
    })}
  </div>
);

const WCard: React.FC<{ t: number; at: number; name: string; from: number; to: number }> = ({ t, at, name, from, to }) => {
  const e = pop(t, at, 0.5);
  const W = 380, Hc = 676;                                   // 9:16, o plano inteiro do celular
  const z = 1 + 0.03 * lin(t, from, to);                     // aproximação mínima, sem cortar o assunto
  return (
    <div style={{ position: "absolute", left: 540 - W / 2, top: 90, width: W, height: Hc, borderRadius: 40, overflow: "hidden", boxShadow: "0 30px 70px rgba(0,0,0,0.45)", border: "4px solid rgba(140,203,255,0.35)", background: BG, transform: `scale(${(0.92 + 0.08 * e).toFixed(4)})`, opacity: Math.min(1, e * 2.5) }}>
      <Sequence from={fr(from)} layout="none">
        <OffthreadVideo src={staticFile(`matheus-fisio/v2-${name}.mp4`)} muted style={{ position: "absolute", inset: 0, width: W, height: Hc, objectFit: "cover", transform: `scale(${z.toFixed(4)})` }} />
      </Sequence>
    </div>
  );
};

// ───── A · gancho desenhado: a pergunta grande em cima; embaixo, a casa longe da clínica por um caminho cheio de curvas.
// No "difícil?" o caminho fica vermelho e o ponto trava. A mesma casa vira a cena azul seguinte (pedido: o começo
// com filmagem ampliada estava feio).
const ROAD = "M392 1445 C 470 1460, 490 1400, 465 1320 S 380 1110, 500 1065 S 670 1160, 640 1300 S 630 1460, 745 1440 S 905 1350, 830 1400";
const SA: React.FC<{ t: number }> = ({ t }) => {
  const draw = io(t, -LEAD + 0.1, C.ficou - 0.1);
  const red = k(t, C.dificil, 0.35);
  const go = 0.42 * io(t, C.fisio, C.ficou + 0.1);               // o ponto anda e trava antes da metade
  const clin = pop(t, C.fisio - 0.05, 0.45);
  const clock = pop(t, C.ficou + 0.05, 0.4);
  const cam = 1 + 0.04 * lin(t, -LEAD, B);
  const roadCol = `rgb(${Math.round(36 + (255 - 36) * red)},${Math.round(82 + (91 - 82) * red)},${Math.round(127 + (95 - 127) * red)})`;
  return (
    <AbsoluteFill style={{ background: BG }}>
      <Col y={295} gap={8}>
        <Mask t={t} at={-LEAD - 0.6}><T size={72}>Sair de casa</T></Mask>
        <Mask t={t} at={C.pra - 0.05}><T size={56}>pra fazer</T></Mask>
        <Mask t={t} at={C.fisio - 0.05}><T size={72} color={SKY}>fisioterapia</T></Mask>
        <Mask t={t} at={C.ficou - 0.05}><T size={56}>ficou</T></Mask>
        <Mask t={t} at={C.dificil - 0.04}><T size={100} color={RED}>difícil?</T></Mask>
      </Col>
      <div style={{ position: "absolute", left: 0, top: 0, width: 1080, height: 1920, transformOrigin: "0 0", transform: `translate(${(540 - 540 * 0.78 * cam).toFixed(1)}px, ${(545 - 943 * 0.78 * cam).toFixed(1)}px) scale(${(0.78 * cam).toFixed(4)})` }}>
        <svg width={1080} height={1920} viewBox="0 0 1080 1920" style={{ position: "absolute", left: 0, top: 0 }} fill="none" strokeLinecap="round" strokeLinejoin="round">
          {/* caminho comprido */}
          <path d={ROAD} stroke={roadCol} strokeWidth={34} pathLength={1} strokeDasharray="1 1" strokeDashoffset={1 - draw} />
          <path d={ROAD} stroke={BG} strokeWidth={5} strokeDasharray="14 18" opacity={draw > 0.98 ? 0.9 : 0} />
          {/* casa (igual à da cena azul) */}
          <g transform="translate(130 1215) scale(0.4)">
            <path d="M20 250 L300 30 L580 250" stroke={SKY} strokeWidth={40} />
            <path d="M75 215 L75 600 L525 600 L525 215" stroke={SKY} strokeWidth={40} />
            <path d="M235 600 L235 435 Q235 420 250 420 L350 420 Q365 420 365 435 L365 600" stroke={WHITE} strokeWidth={28} />
          </g>
          {/* clínica com a cruz */}
          <g transform={`translate(830 1300) scale(${clin.toFixed(3)})`} opacity={Math.min(1, clin * 2)}>
            <rect x={-95} y={-150} width={190} height={190} rx={22} stroke={SKY} strokeWidth={14} />
            <rect x={-42} y={-108} width={84} height={84} rx={14} fill={BLUE} />
            <path d="M0 -90 L0 -42 M-24 -66 L24 -66" stroke={WHITE} strokeWidth={14} />
          </g>
          {/* relógio: o tempo passando */}
          <g transform={`translate(560 1075) scale(${clock.toFixed(3)})`} opacity={Math.min(1, clock * 2)}>
            <circle cx={0} cy={-80} r={52} fill={BG} stroke={red > 0.5 ? RED : SKY} strokeWidth={10} />
            <path d="M0 -80 L0 -112" stroke={WHITE} strokeWidth={9} transform={`rotate(${(t * 220).toFixed(1)} 0 -80)`} />
            <path d="M0 -80 L20 -80" stroke={WHITE} strokeWidth={9} />
          </g>
        </svg>
        {/* o ponto que tenta chegar */}
        <div style={{ position: "absolute", left: 0, top: 0, width: 34, height: 34, marginLeft: -17, marginTop: -17, borderRadius: "50%", background: red > 0.5 ? RED : WHITE, boxShadow: `0 0 0 10px ${red > 0.5 ? "rgba(255,91,95,0.25)" : "rgba(140,203,255,0.3)"}`, offsetPath: `path("${ROAD}")`, offsetDistance: `${(go * 100).toFixed(2)}%`, offsetRotate: "0deg", opacity: lin(t, C.fisio - 0.1, C.fisio + 0.05) } as React.CSSProperties} />
      </div>
    </AbsoluteFill>
  );
};

// ───── B · a fisioterapia vai até você: tudo branco, 2 níveis ─────
const SB: React.FC<{ t: number }> = ({ t }) => {
  const hs = 0.66;
  const hx = 540 - 300 * hs, hy = 560;
  const doorX = hx + 300 * hs, doorY = hy + 520 * hs;
  const roof = k(t, C.entao + 0.1, 0.5), walls = k(t, C.entao + 0.35, 0.5), door = k(t, C.vai, 0.4);
  const pin = k(t, C.voce - 0.25, 0.4);
  const zoom = io(t, BZ - 0.15, CN + 0.05);
  const z = 1 + 9 * zoom * zoom;
  return (
    <AbsoluteFill style={{ background: BLUE, overflow: "hidden" }}>
      <div style={{ position: "absolute", inset: 0, transform: `scale(${z.toFixed(4)})`, transformOrigin: `${doorX}px ${doorY}px` }}>
        <Col y={300} gap={0}>
          <Mask t={t} at={C.entao - 0.05}><T size={68}>a fisioterapia</T></Mask>
          <Mask t={t} at={C.vai - 0.05}><T size={68}>vai</T></Mask>
          <Mask t={t} at={C.vai + 0.25}><T size={124}>até você</T></Mask>
        </Col>
        <svg width={1080} height={1920} viewBox="0 0 1080 1920" style={{ position: "absolute", left: 0, top: 0 }} fill="none" strokeLinecap="round" strokeLinejoin="round">
          <g transform={`translate(${hx} ${hy}) scale(${hs})`}>
            <path d="M20 250 L300 30 L580 250" stroke={BG} strokeWidth={36} pathLength={1} strokeDasharray="1 1" strokeDashoffset={1 - roof} />
            <path d="M75 215 L75 600 L525 600 L525 215" stroke={BG} strokeWidth={36} pathLength={1} strokeDasharray="1 1" strokeDashoffset={1 - walls} />
            <rect x={235} y={420} width={130} height={180} rx={14} fill={BG} opacity={door * (0.3 + 0.7 * pin)} />
            <path d="M235 600 L235 435 Q235 420 250 420 L350 420 Q365 420 365 435 L365 600" stroke={WHITE} strokeWidth={24} pathLength={1} strokeDasharray="1 1" strokeDashoffset={1 - door} />
            {pin > 0 && (
              <g transform={`translate(300 ${(-80 + 560 * pin).toFixed(1)}) scale(${(0.6 + 0.4 * pop(t, C.voce - 0.25, 0.45)).toFixed(3)})`} opacity={Math.min(1, pin * 3)}>
                <path d="M0 0 C-60 -70 -60 -150 0 -150 C60 -150 60 -70 0 0 Z" fill={WHITE} />
                <circle cx={0} cy={-100} r={22} fill={BLUE} />
              </g>
            )}
          </g>
        </svg>
      </div>
    </AbsoluteFill>
  );
};

// ───── C · Matheus (cartão com vídeo + nome embaixo) ─────
const SC: React.FC<{ t: number }> = ({ t }) => (
  <AbsoluteFill style={{ background: BG }}>
    <WCard t={t} at={CN - 0.1} name="nome" from={CN} to={D + 0.3} />
    <Col y={880} gap={12}>
      <Mask t={t} at={C.meu}><T size={96}>Matheus</T></Mask>
      <Swap t={t} items={[
        [<Cap key="a" size={34} color={SKY}>Fisioterapeuta</Cap>, C.sou + 0.1],
        [<div key="b"><Cap size={32} color={SKY}>especializado em</Cap><div style={{ height: 6 }} /><Cap size={32} color={SKY}>quiropraxia</Cap></div>, C.espec],
      ]} />
    </Col>
  </AbsoluteFill>
);

// ───── D · na sua casa (cartão) ─────
const SD: React.FC<{ t: number }> = ({ t }) => (
  <AbsoluteFill style={{ background: BG }}>
    <WCard t={t} at={D - 0.1} name="casa" from={D} to={E + 0.3} />
    <Col y={870} gap={10}>
      <Mask t={t} at={C.atendo}><Cap size={40}>Eu atendo</Cap></Mask>
      <div style={{ display: "flex", alignItems: "baseline", gap: 26 }}>
        <Mask t={t} at={C.casa - 0.3}><T size={64}>na sua</T></Mask>
        <Mask t={t} at={C.casa - 0.2}><T size={104} color={SKY}>casa</T></Mask>
      </div>
    </Col>
  </AbsoluteFill>
);

// ───── E · a casa em corte: zoom do quarto para a sala (desenho) ─────
const SE: React.FC<{ t: number }> = ({ t }) => {
  const q = io(t, C.quarto - 0.15, C.quarto + 0.45);
  const s = io(t, C.sala - 0.2, C.sala + 0.45);
  // no quadrado a casa fica inteira dentro da margem: sem zoom no cômodo, só um avanço leve; o cômodo falado acende
  const vx = 540, vy = 1105;
  const sc = 1 + 0.04 * lin(t, E, F);
  const draw = k(t, E, 0.6);
  const pinX = 540 + (365 - 540) * q + (715 - 365) * s;
  const pinY = 1180 - 30 * Math.abs(Math.sin(Math.PI * s));
  const litQ = q * (1 - s), litS = s;
  return (
    <AbsoluteFill style={{ background: BG }}>
      <Col y={238} gap={6}>
        <Mask t={t} at={C.levo + 0.05}><Cap size={38}>Levo o tratamento</Cap></Mask>
        <Swap t={t} items={[
          [<div key="a"><T size={66}>até o seu</T><div style={{ height: 4 }} /><T size={116} color={SKY}>quarto</T></div>, C.levo + 0.3],
          [<div key="b"><T size={66}>até a sua</T><div style={{ height: 4 }} /><T size={150} color={SKY}>sala</T></div>, C.sala],
        ]} />
      </Col>
      <div style={{ position: "absolute", inset: 0, clipPath: "inset(415px 0 70px 0)" }}>
        <svg width={1080} height={1920} viewBox="0 0 1080 1920" style={{ position: "absolute", left: 0, top: 0, transformOrigin: "0 0", transform: `translate(${(540 - vx * sc * 0.82).toFixed(1)}px, ${(700 - vy * sc * 0.82).toFixed(1)}px) scale(${(sc * 0.82).toFixed(4)})` }} fill="none" strokeLinecap="round" strokeLinejoin="round">
          {/* cômodos acendem quando falados */}
          <rect x={196} y={1010} width={338} height={424} fill={BLUE} opacity={0.28 * litQ} />
          <rect x={546} y={1010} width={338} height={424} fill={BLUE} opacity={0.28 * litS} />
          <g stroke={SKY} strokeWidth={14} pathLength={1} strokeDasharray="1 1" strokeDashoffset={1 - draw}>
            <path d="M150 990 L540 780 L930 990" pathLength={1} />
            <path d="M190 970 L190 1440 L890 1440 L890 970" pathLength={1} />
            <path d="M540 1010 L540 1440" pathLength={1} />
            <path d="M130 1440 L950 1440" pathLength={1} />
          </g>
          {/* quarto: cama e criado-mudo */}
          <g opacity={k(t, E + 0.3, 0.4)} stroke={WHITE} strokeWidth={10}>
            <rect x={230} y={1320} width={250} height={60} rx={14} />
            <path d="M230 1380 L230 1420 M480 1380 L480 1420" />
            <path d="M230 1320 L230 1260" />
            <rect x={250} y={1290} width={80} height={30} rx={12} fill={SKY} stroke="none" />
          </g>
          {/* sala: sofá */}
          <g opacity={k(t, E + 0.45, 0.4)} stroke={WHITE} strokeWidth={10}>
            <rect x={600} y={1255} width={230} height={70} rx={20} />
            <rect x={590} y={1325} width={250} height={60} rx={16} />
            <path d="M610 1385 L610 1420 M820 1385 L820 1420" />
            <rect x={640} y={1270} width={60} height={50} rx={12} fill={SKY} stroke="none" />
          </g>
          {/* pino que vai de cômodo em cômodo */}
          <g transform={`translate(${pinX.toFixed(1)} ${pinY.toFixed(1)}) scale(${(0.8 * pop(t, E + 0.2, 0.45)).toFixed(3)})`}>
            <path d="M0 0 C-50 -60 -50 -125 0 -125 C50 -125 50 -60 0 0 Z" fill={WHITE} stroke="none" />
            <circle cx={0} cy={-84} r={18} fill={BLUE} stroke="none" />
          </g>
        </svg>
      </div>
    </AbsoluteFill>
  );
};

// ───── F · eu levo tudo (fundo claro; igual à v4) ─────
const IcoBall: React.FC<{ s: number; t: number }> = ({ s, t }) => (
  <svg width={s} height={s} viewBox="0 0 100 100" fill="none" stroke={SKY} strokeWidth={6} strokeLinecap="round">
    <g transform={`rotate(${(t * 60).toFixed(1)} 50 50)`}><circle cx={50} cy={50} r={40} /><path d="M14 38 Q50 58 86 38" /><path d="M20 72 Q50 52 80 72" /></g>
  </svg>
);
const IcoBand: React.FC<{ s: number; t: number }> = ({ s, t }) => {
  const w = 8 * Math.sin(t * 5);
  return (
    <svg width={s} height={s} viewBox="0 0 100 100" fill="none" stroke={SKY} strokeWidth={7} strokeLinecap="round" strokeLinejoin="round">
      <path d={`M14 30 Q50 ${(10 + w).toFixed(1)} 86 30`} /><path d={`M14 30 Q30 ${(70 - w).toFixed(1)} 50 82 Q70 ${(70 - w).toFixed(1)} 86 30`} />
      <rect x={6} y={22} width={16} height={16} rx={5} fill={SKY} /><rect x={78} y={22} width={16} height={16} rx={5} fill={SKY} />
    </svg>
  );
};
const IcoPedal: React.FC<{ s: number; t: number }> = ({ s, t }) => {
  const a = t * 4;
  const px = 50 + 20 * Math.cos(a), py = 46 + 20 * Math.sin(a);
  return (
    <svg width={s} height={s} viewBox="0 0 100 100" fill="none" stroke={SKY} strokeWidth={6} strokeLinecap="round" strokeLinejoin="round">
      <path d="M14 86 L86 86" /><path d="M30 86 L42 54 M70 86 L58 54" /><circle cx={50} cy={46} r={10} />
      <path d={`M50 46 L${px.toFixed(1)} ${py.toFixed(1)}`} /><path d={`M${(px - 10).toFixed(1)} ${py.toFixed(1)} L${(px + 10).toFixed(1)} ${py.toFixed(1)}`} strokeWidth={9} />
      <path d={`M50 46 L${(100 - px).toFixed(1)} ${(92 - py).toFixed(1)}`} /><path d={`M${(90 - px).toFixed(1)} ${(92 - py).toFixed(1)} L${(110 - px).toFixed(1)} ${(92 - py).toFixed(1)}`} strokeWidth={9} />
    </svg>
  );
};
const SF: React.FC<{ t: number }> = ({ t }) => {
  const rows: [React.FC<{ s: number; t: number }>, string, number][] = [[IcoBall, "Bola", C.bola - 0.05], [IcoBand, "Faixa\nelástica", C.faixa - 0.05], [IcoPedal, "Pedaleira", C.pedal - 0.05]];
  const rh = 214, gap = 26;
  const cam = 1 + 0.04 * lin(t, F, G);
  return (
    <AbsoluteFill style={{ background: PAPER }}>
      <div style={{ position: "absolute", inset: 0, transform: `scale(${cam.toFixed(4)})` }}>
        <div style={{ position: "absolute", left: 140, right: 140, top: 540, transform: "translateY(-50%)", display: "flex", flexDirection: "column", gap }}>
          <div style={{ display: "flex", justifyContent: "center", marginBottom: 4 }}>
            <Mask t={t} at={F + 0.02}><div style={{ fontFamily: FONT, fontWeight: 900, fontSize: 76, lineHeight: 1, letterSpacing: "-0.02em", textTransform: "uppercase", color: BG, whiteSpace: "nowrap" }}>Eu levo <span style={{ color: BLUE }}>tudo</span></div></Mask>
          </div>
          {rows.map(([Ico, label, at], i) => {
            const e = pop(t, F + 0.12 + i * 0.14, 0.45);
            const on = k(t, at, 0.3);
