// ───── montagem: cada troca de um jeito ─────
export const MatheusFisioV7Q: React.FC = () => {
  const t = useCurrentFrame() / FPS - LEAD;
  const fB = io(t, B - 0.05, B + 0.3);          // A→B: círculo azul inunda
  const pC = io(t, CN - 0.12, CN + 0.12);       // B→C: zoom pela porta, o cartão aparece de dentro dela
  const pD = io(t, D - 0.2, D + 0.2);           // C→D: faixa inclinada
  const pE = io(t, E - 0.2, E + 0.15);          // D→E: a nova desce de cima
  const pF = io(t, F - 0.2, F + 0.15);          // E→F: abre do meio para os lados (fundo claro)
  const pG = io(t, G - 0.2, G + 0.15);          // F→G: empurra para a esquerda
  const pH = io(t, H - 0.25, H + 0.15);         // G→H: azul inunda em círculo a partir do cartão
  const pI = io(t, I - 0.25, I + 0.15);         // H→I: azul-marinho sobe de baixo
  const pJ = io(t, J - 0.2, J + 0.2);           // I→J: círculo azul do centro
  const band = -30 + 160 * pD;
  return (
    <AbsoluteFill style={{ background: BG, overflow: "hidden" }}>
      {t < B + 0.35 && <SA t={t} />}
      {fB > 0 && t < CN + 0.15 && <AbsoluteFill style={{ clipPath: `circle(${(fB * 80).toFixed(2)}% at 50% 50%)` }}><SB t={t} /></AbsoluteFill>}
      {pC > 0 && t < D + 0.25 && <AbsoluteFill style={{ opacity: pC, transform: `scale(${(1.15 - 0.15 * pC).toFixed(4)})` }}><SC t={t} /></AbsoluteFill>}
      {pD > 0 && pD < 1 && <AbsoluteFill style={{ background: BLUE, clipPath: `polygon(0 0, ${band + 12}% 0, ${band - 18}% 100%, 0 100%)` }} />}
      {pD > 0 && t < E + 0.2 && <AbsoluteFill style={{ clipPath: `polygon(0 0, ${band}% 0, ${band - 30}% 100%, 0 100%)`, transform: `translateY(${(100 * pE).toFixed(2)}%)` }}><SD t={t} /></AbsoluteFill>}
      {pE > 0 && t < F + 0.2 && <AbsoluteFill style={{ transform: `translateY(${(-100 + 100 * pE).toFixed(2)}%)` }}><SE t={t} /></AbsoluteFill>}
      {pF > 0 && t < G + 0.2 && <AbsoluteFill style={{ clipPath: `inset(0 ${(50 - 50 * pF).toFixed(2)}% 0 ${(50 - 50 * pF).toFixed(2)}%)`, transform: `translateX(${(-100 * pG).toFixed(2)}%)` }}><SF t={t} /></AbsoluteFill>}
      {pG > 0 && t < H + 0.2 && <AbsoluteFill style={{ transform: `translateX(${(100 - 100 * pG).toFixed(2)}%)` }}><SG t={t} /></AbsoluteFill>}
      {pH > 0 && t < I + 0.2 && <AbsoluteFill style={{ clipPath: `circle(${(pH * 125).toFixed(2)}% at 50% 31%)` }}><SHh t={t} /></AbsoluteFill>}
      {pI > 0 && t < J + 0.25 && <AbsoluteFill style={{ transform: `translateY(${(100 - 100 * pI).toFixed(2)}%)` }}><SI t={t} /></AbsoluteFill>}
      {pJ > 0 && <AbsoluteFill style={{ clipPath: `circle(${(pJ * 80).toFixed(2)}% at 50% 50%)` }}><SJ t={t} /></AbsoluteFill>}
    </AbsoluteFill>
  );
};

